'use strict';
// Embedded fonts (SIL Open Font License 1.1, Indian Type Foundry; from @fontsource/kalam 5.3.0 and
// @fontsource/poppins 5.3.0, latin subset). Data URLs because Chrome blocks file:// fonts. The core waits for
// every promise in _photoLoads before the first frame, so text never renders in a fallback face.
const FONT_FACES = [
 ["Kalam", 400, 'data:font/woff2;base64,'],
 ["Kalam", 700, 'data:font/woff2;base64,'],
 ["Poppins", 400, 'data:font/woff2;base64,'],
 ["Poppins", 500, 'data:font/woff2;base64,'],
 ["Poppins", 600, 'data:font/woff2;base64,'],
 ["Poppins", 700, 'data:font/woff2;base64,'],
];
for (const [family, weight, src] of FONT_FACES) { const face = new FontFace(family, `url(${src})`, { weight: String(weight) }); document.fonts.add(face); _photoLoads.push(face.load()); }
